//go:build ignore
package main
import("encoding/json";"os";"net/http";"net/http/httptest";"io";"strings";"sync";"github.com/Tencent/WeKnora/internal/utils")
type Request struct{Method string `json:"method"`;Path string `json:"path"`;Body string `json:"body"`;Headers map[string]string `json:"headers"`}
type Case struct{Method string `json:"method"`;Mode string `json:"mode"`;Status int `json:"redirect_status"`;Result int `json:"result"`;Error string `json:"error_kind"`;Requests []Request `json:"requests"`}
func main(){os.Setenv("SSRF_WHITELIST","127.0.0.1,localhost");os.Setenv("SSRF_WHITELIST_EXTRA","");utils.ResetSSRFWhitelistForTest();out:=[]Case{};var active *Case;var base string;var mu sync.Mutex;keys:=[]string{"Accept","Accept-Language","User-Agent","Authorization","Cookie","Content-Type","X-Request-ID"}
 server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){mu.Lock();defer mu.Unlock();headers:=map[string]string{};for _,key:=range keys{headers[key]=r.Header.Get(key)};body,_:=io.ReadAll(r.Body);active.Requests=append(active.Requests,Request{r.Method,r.URL.RequestURI(),string(body),headers});if r.URL.Path=="/final"{w.WriteHeader(200);return};target:=base+"/final";if active.Mode=="cross"{target=strings.Replace(base,"127.0.0.1","localhost",1)+"/final"};if active.Mode=="cycle"{target=base+"/start"};w.Header().Set("Location",target);w.WriteHeader(active.Status)}));defer server.Close();base=server.URL
 for _,method:=range []string{"GET","HEAD","POST"}{for _,mode:=range []string{"same","cross","cycle"}{for _,status:=range []int{303,307}{c:=Case{Method:method,Mode:mode,Status:status,Requests:[]Request{}};active=&c;var body io.Reader;if method=="POST"{body=strings.NewReader("{}")} ;req,_:=http.NewRequest(method,base+"/start",body);for _,key:=range keys{req.Header.Set(key,"fixture-"+key)};client:=utils.NewSSRFSafeHTTPClient(utils.SSRFSafeHTTPClientConfig{MaxRedirects:5});response,err:=client.Do(req);if err!=nil{if strings.Contains(err.Error(),"stopped after 5 redirects"){c.Error="redirect_limit"}else if strings.Contains(err.Error(),"cross-origin request replay is forbidden"){c.Error="cross_origin"}else{panic(err)}}else{c.Result=response.StatusCode;response.Body.Close()};out=append(out,c)}}};json.NewEncoder(os.Stdout).Encode(out)
}
